style.css:
@media (prefers-color-scheme: dark) {
  body {
    background-color: #121212;
    color: #e0e0e0;
  }

  a {
    color: #bb86fc;
  }

  .navbar, .footer, .header {
    background-color: #1f1f1f;
  }

  .card, .block, .region {
    background-color: #1e1e1e;
    border-color: #333;
  }

  input, select, textarea, button {
    background-color: #2c2c2c;
    color: #e0e0e0;
    border-color: #444;
  }
}
